<?php namespace Workspace;
$owner=$user['role']==='owner';$codes=array_column($accounts,'code','id');$options=[];foreach($accounts as $a)$options[$a['id']]=$a['code'].' · '.$a['name'];
$manual=[];foreach($options as $id=>$label)if($codes[$id]!=='1000'&&!isset(BOOK_AP_ACCOUNTS[$codes[$id]]))$manual[$id]=$label;
$today=gmdate('Y-m-d');$selected=$period?['period'=>$period['id']]:[];
$state=$active?'Учёт активирован':($opening?'Ожидает подтверждения бухгалтера':'Не активирован');
?>
<section class="panel"><h2><?= h($state) ?></h2><?php if(!$writable): ?><p>Доступ только для чтения: для операций нужны права создания и согласования платежей во всех проектах.</p><?php endif ?><p>Управленческий журнал: кассовый метод и отдельные начисления поставщиков. <a href="<?= h(url('books')) ?>">Финансовые книги</a>. Все суммы раздельно по валютам. Журнал организации доступен только владельцу и бухгалтеру с финансовым доступом ко всем проектам.</p>
<?php if($reconcile): ?><p><strong><?= $reconcile['ok']?'Кассовая книга сходится с журналом':'Обнаружено расхождение — закрытие периода заблокировано' ?></strong> · <?= h($reconcile['count']) ?> проводок, отсутствующих или несовпадающих: <?= h($reconcile['missing']) ?>.</p><?php endif ?>
<p>Текущая кассовая книга: <?= h($snapshot['count']) ?> записей, с <?= h($snapshot['first']??'—') ?> по <?= h($snapshot['last']??'—') ?>. SHA-256: <code><?= h($snapshot['digest']) ?></code></p>
<div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Поступления (нетто)</th><th>Расходы (нетто)</th><th>Движение</th></tr></thead><tbody><?php foreach($snapshot['totals'] as $c=>$t): ?><tr><td><?= h($c) ?></td><?php foreach(['income','expense','net'] as $k): ?><td><?= h(money($t[$k])) ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>План счетов</h2><?php if(!$accounts): ?><p>Создайте стандартные счета перед подготовкой начальных остатков.</p><?php if($owner): ?><form method="post"><?php formFields('accounting.init') ?><button>Создать стандартный план</button></form><?php endif ?><?php else: ?><div class="tablewrap"><table><thead><tr><th>Код</th><th>Название</th><th>Тип</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><?= h($a['code']) ?></td><td><?= h($a['name']) ?></td><td><?= h(ACCOUNT_KINDS[$a['kind']]) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if($owner): ?><details><summary>Добавить счёт</summary><form method="post"><?php formFields('accounting.account') ?><label>Код<input name="code" maxlength="20" required></label><label>Название<input name="name" maxlength="180" required></label><label>Тип<select name="kind"><?php selectOptions(ACCOUNT_KINDS) ?></select></label><button>Добавить</button></form></details><?php endif ?></section>
<section class="panel"><h2>Отчётные периоды</h2><?php if($periods): ?><form method="get"><input type="hidden" name="p" value="accounting"><label>Период<select name="period"><?php $periodOptions=[];foreach($periods as $p)$periodOptions[$p['id']]=$p['starts_on'].' — '.$p['ends_on'].($p['closed_at']!==null?' · закрыт':' · открыт');selectOptions($periodOptions,$period['id']??null) ?></select></label><button>Показать</button></form><?php endif ?>
<?php if($writable&&(!$periods||$active)): ?><details <?= !$periods?'open':'' ?>><summary>Создать период</summary><form method="post"><?php formFields('accounting.period') ?><label>Начало<input type="date" name="starts_on" value="<?= h($periods?gmdate('Y-m-d',strtotime($periods[0]['ends_on'].' +1 day')):($snapshot['first']??$today)) ?>" required></label><label>Окончание<input type="date" name="ends_on" value="<?= h($periods?'':gmdate('Y-m-t')) ?>" required></label><button>Создать</button></form></details><?php endif ?>
<?php if($period&&!$active&&$owner): ?><details><summary>Исправить начальный период (до приёмки)</summary><form method="post"><?php formFields('accounting.period_edit') ?><input type="hidden" name="id" value="<?= h($period['id']) ?>"><label>Начало<input type="date" name="starts_on" value="<?= h($period['starts_on']) ?>" required></label><label>Окончание<input type="date" name="ends_on" value="<?= h($period['ends_on']) ?>" required></label><button>Изменить, затем подготовить сверку заново</button></form></details><?php endif ?>
<?php if($writable&&$active&&$period&&$period['closed_at']===null&&$period['ends_on']<$today): ?><form method="post"><?php formFields('accounting.close') ?><input type="hidden" name="id" value="<?= h($period['id']) ?>"><p>Закрытие необратимо. Проверьте обороты и незавершённые платежи.</p><button>Закрыть период</button></form><?php endif ?></section>
<section class="panel"><h2>Перенос кассовой книги и начальные остатки</h2><p>Правило: Дт 1000 / Кт 4000 для поступлений, Дт 5000 / Кт 1000 для расходов. Сторно меняет стороны исходной проводки. Начальные остатки задаются на начало первого периода, до исторических движений.</p>
<?php if($opening): $saved=json_decode($opening['snapshot'],true,512,JSON_THROW_ON_ERROR);$pairs=json_decode($opening['pairs'],true,512,JSON_THROW_ON_ERROR);$expected=json_decode($opening['expected'],true,512,JSON_THROW_ON_ERROR); ?>
<p>Сверка #<?= h($opening['id']) ?>, редакция <?= h($opening['version']) ?>. Подготовил пользователь #<?= h($opening['prepared_by']) ?>. Основание: <?= h($opening['evidence']) ?>.</p><p>Начальный период снимка: <?= h(implode(' — ',$saved['period_dates']??[])) ?>.</p><p>Снимок: <?= h($saved['count']) ?> записей · <code><?= h($opening['cash_digest']) ?></code> · <?= h(hash_equals($opening['cash_digest'],$snapshot['digest'])?'Касса не изменилась':'Касса изменилась после снимка') ?></p>
<div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Движение по снимку</th><th>Контрольный остаток</th></tr></thead><tbody><?php foreach(CURRENCIES as $c): ?><tr><td><?= h($c) ?></td><td><?= h(money($saved['totals'][$c]['net'])) ?></td><td><?= h(money($expected[$c])) ?></td></tr><?php endforeach ?></tbody></table></div>
<h3>Начальные проводки</h3><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Дт</th><th>Кт</th><th>Сумма</th></tr></thead><tbody><?php foreach($pairs as $p): ?><tr><td><?= h($p['currency']) ?></td><td><?= h($codes[$p['debit']]) ?></td><td><?= h($codes[$p['credit']]) ?></td><td><?= h(money($p['amount'])) ?></td></tr><?php endforeach ?></tbody></table></div>
<?php if($active): ?><p>Подтвердил бухгалтер #<?= h($opening['approved_by']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$opening['approved_at'])) ?> UTC. <?= h($opening['review_note']) ?></p><?php elseif(!$owner&&$writable): ?><form method="post"><?php formFields('accounting.approve') ?><input type="hidden" name="id" value="<?= h($opening['id']) ?>"><input type="hidden" name="version" value="<?= h($opening['version']) ?>"><label>Подтверждение сверки с первичными документами<input name="note" maxlength="500" required></label><button>Подтвердить остатки и перенести кассу</button></form><?php endif ?><?php endif ?>
<?php if(!$active&&$owner&&$period&&$accounts): ?><form method="post"><?php formFields('accounting.prepare') ?><input type="hidden" name="period_id" value="<?= h($period['id']) ?>"><label>Начальные проводки (валюта дебет кредит сумма, по строке; пусто — без остатков)<textarea name="pairs" rows="5" placeholder="EUR 1000 3000 500.00"><?php if(isset($pairs))foreach($pairs as $p)echo h($p['currency'].' '.$codes[$p['debit']].' '.$codes[$p['credit']].' '.money($p['amount'],false))."\n"; ?></textarea></label><p>Остатки денег после всех движений кассовой книги по фактической выписке/кассе:</p><?php foreach(CURRENCIES as $c): ?><label><?= h($c) ?><input name="<?= h($c) ?>" value="<?= h(isset($expected)?money($expected[$c],false):'0') ?>" required></label><?php endforeach ?><label>Основание (идентификатор выписки / акт инвентаризации)<input name="evidence" maxlength="500" value="<?= h($opening['evidence']??'') ?>" required></label><button>Подготовить сверку</button></form><?php endif ?></section>
<?php if($active&&$period): ?><section class="panel"><h2>Оборотно-сальдовая ведомость</h2><p>Сальдо со знаком: положительное — дебетовое, отрицательное — кредитовое. Начальные проводки входят в начальное сальдо, а не в обороты.</p><div class="tablewrap"><table><thead><tr><th>Валюта</th><th>Счёт</th><th>Начальное</th><th>Дебет</th><th>Кредит</th><th>Конечное</th></tr></thead><tbody><?php foreach($trial['rows'] as $r): ?><tr><td><?= h($r['currency']) ?></td><td><?= h($r['code'].' · '.$r['name']) ?></td><?php foreach(['opening','debit','credit','closing'] as $k): ?><td><?= h(money($r[$k])) ?></td><?php endforeach ?></tr><?php endforeach ?><?php foreach($trial['totals'] as $c=>$r): ?><tr><th><?= h($c) ?></th><th><?= $r['opening']===0&&$r['closing']===0&&$r['debit']===$r['credit']?'Сходится':'Расхождение' ?></th><?php foreach(['opening','debit','credit','closing'] as $k): ?><th><?= h(money($r[$k])) ?></th><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><h2>Журнал проводок</h2><?php if($writable&&$period['closed_at']===null): ?><details><summary>Новая ручная проводка (без счёта 1000)</summary><form method="post"><?php formFields('accounting.post') ?><label>Дата<input type="date" name="booked_on" value="<?= h(min($period['ends_on'],$today)) ?>" min="<?= h($period['starts_on']) ?>" max="<?= h(min($period['ends_on'],$today)) ?>" required></label><label>Валюта<select name="currency"><?php selectOptions(array_combine(CURRENCIES,CURRENCIES)) ?></select></label><label>Дебет<select name="debit"><?php selectOptions($manual) ?></select></label><label>Кредит<select name="credit"><?php selectOptions($manual) ?></select></label><label>Сумма<input name="amount" required></label><label>Проект<select name="project_id"><?php selectOptions([''=>'Общеорганизационная']+$projects) ?></select></label><label>Основание<input name="memo" maxlength="500" required></label><button>Провести</button></form></details><?php endif ?>
<div class="tablewrap"><table><thead><tr><th>№ / дата</th><th>Проект / тип</th><th>Дт</th><th>Кт</th><th>Сумма</th><th>Основание</th></tr></thead><tbody><?php foreach($entries as $e): ?><tr><td>#<?= h($e['id']) ?> · <?= h($e['booked_on']) ?></td><td><?= h($projects[$e['project_id']]??'—') ?> · <?= h($e['kind']) ?></td><td><?= h($e['debit_code']) ?></td><td><?= h($e['credit_code']) ?></td><td><?= h(money((int)$e['amount_minor']).' '.$e['currency']) ?></td><td><?= h($e['memo']) ?> · <?= h($e['actor_name']) ?><?php if($e['reversal_of']): ?> · Сторно #<?= h($e['reversal_of']) ?><?php endif ?><?php if($e['reversed_by']): ?> · Сторнировано #<?= h($e['reversed_by']) ?><?php elseif($writable&&$e['kind']==='manual'&&!isset(BOOK_AP_ACCOUNTS[$e['credit_code']])&&!isset(BOOK_AP_ACCOUNTS[$e['debit_code']])): ?><details><summary>Сторно</summary><form method="post"><?php formFields('accounting.reverse') ?><input type="hidden" name="id" value="<?= h($e['id']) ?>"><label>Дата<input name="booked_on" type="date" value="<?= h($today) ?>" required></label><label>Причина<input name="memo" maxlength="500" required></label><button>Сторнировать</button></form></details><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if($nextBefore): ?><a href="<?= h(url('accounting',$selected+['before'=>$nextBefore])) ?>">Следующие записи</a><?php endif ?></section><?php endif ?>
